from pathlib import Path
import subprocess,html
root=Path(__file__).parent
D=[]
def add(name,title,caption,nodes,edges,groups=(),direction='LR'):
    lines=['digraph G {',f'graph [rankdir={direction},bgcolor="white",pad="0.25",nodesep="0.35",ranksep="0.55",fontname="DejaVu Sans"];','node [shape=box,style="rounded,filled",fillcolor="#eaf2ff",color="#6482a6",fontname="DejaVu Sans",fontsize=11,margin="0.15,0.1"];','edge [fontname="DejaVu Sans",fontsize=9,color="#36546c",arrowsize=0.7];']
    for key,label,color in nodes:
        lines.append(f'{key} [label="{label}",fillcolor="{color or "#eaf2ff"}"];')
    for i,(label,members) in enumerate(groups):
        lines.append(f'subgraph cluster_{i} {{label="{label}";color="#b5c5d6";style="rounded";'+''.join(x+';' for x in members)+'}')
    for a,b,label,kind in edges:
        style='style=dashed,color="#936238"' if kind=='ctrl' else 'color="#326b70",penwidth=1.4'
        lines.append(f'{a} -> {b} [label="{label}",{style}];')
    lines.append('}')
    (root/(name+'.dot')).write_text('\n'.join(lines))
    subprocess.run(['dot','-Tsvg',str(root/(name+'.dot')),'-o',str(root/(name+'.svg'))],check=True)
    D.append((name,title,caption))
