parts=['<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NPU v0.5 架构图</title><style>body{font-family:system-ui,sans-serif;margin:0;background:#f2f5f9;color:#172b43}main{max-width:1500px;margin:auto;padding:24px}section{background:white;border:1px solid #d9e2ef;border-radius:12px;padding:20px;margin:24px 0}svg{width:100%;height:auto;min-width:650px}.canvas{overflow:auto}p{line-height:1.7}a{color:#225f9b}nav{line-height:2}small{color:#596b7d}</style><main><h1>NPU v0.5 架构图</h1><p>Qwen3-8B · MPU / VPU / DMA / DCU · prefill + decode</p><p>实线：数据；虚线：控制/事件。当前为设计图，非已实现RTL。可选第三KV slot与未测浮点延迟均未冻结。</p><nav>']
