md=['# NPU v0.5 架构图\n\n优先查看同目录 `architecture.html`：所有SVG内嵌，无需网络。实线为数据，虚线为控制。\n']
for name,title,cap in D:
    svg=(root/(name+'.svg')).read_text();svg=svg[svg.index('<svg'):]
